UPDATE REPLIES
   SET CONTENT = #{modifyReplies.content}
     , MDFY_DT = SYSDATE
     , FILE_SET_ID = #{modifyReplies.fileSetId}
 WHERE ID = #{replyId}
   AND ARTICLE_ID = #{articleId}
   AND EMAIL = #{modifyReplies.email}
   AND DEL_YN = 'N'

UPDATE REPLIES
   SET DEL_YN = 'Y'
     , MDFY_DT = SYSDATE
 WHERE ID = #{replyId}
   AND ARTICLE_ID = #{articleId}
   AND DEL_YN = 'N'

UPDATE REPLIES
   SET RECOMMEND_CNT = RECOMMEND_CNT + 1
 WHERE ID = #{replyId}
   AND ARTICLE_ID = #{articleId}
   AND DEL_YN = 'N'
